// ProposalSummary: The OpenProposal `ProposalSummary` profile: the fields of the `Proposal` document that the specification lists for it.
type ProposalSummary struct {
	// Description: Prose, not a name. Where the "why buy" case is made, including which channels a multi-channel proposal spans
	Description PlainString `json:"description"`
	// LineItems: The full form's line items, each as a summary. In a manifest entry, only those § 2.3 lists
	LineItems List[LineItemSummary] `json:"line_items,omitzero"`
	// OfferWindow: The window the offer holds: it does not hold before `start` or after `end`. This is the offer window, not the campaign flight
	OfferWindow *Interval `json:"offer_window,omitempty"`
	// Packages: The full form's packages, each as a summary. In a manifest entry, only those § 2.3 lists
	Packages List[PackageSummary] `json:"packages,omitzero"`
	// ProposalId: Identifies the proposal. Unique within `seller.domain`
	ProposalId PlainString `json:"proposal_id"`
	// Seller: The proposal's `seller`, projected to `domain` and `legal_name`.
	Seller ProposalSummaryParty `json:"seller"`
	// Version: Monotonically increasing revision number, starting at 1, held by the seller. Each version is a snapshot of the proposal's offered terms (§ 4.1.3). A version is frozen at the earliest of: the proposal's `status` leaving `draft`; a `negotiation_history[]` or `assent[]` entry naming it; a counterparty receiving it in any representation (§ 2.1). The offered terms of a frozen version MUST NOT change; a change to them creates version `n+1`. The values § 4.1.3 lists as not offered terms change without a new version
	Version SafeInteger `json:"version"`
}

